fn all_characters_same(char_arr: &Vec<char>) -> bool {
    // If there are 0 or 1 elements, the condition holds vacuously.
    if char_arr.len() <= 1 {
        return true;
    }
    // Take the first character as reference
    let first = char_arr[0];
    // Check that every subsequent character equals the first
    for &c in &char_arr[1..] {
        if c != first {
            return false;
        }
    }
    true
}

